def make_default_short_help(help, max_length=45):
    """Returns a condensed version of the help text that can be shown in
    the command list.  The text is shortened to the first sentence if it
    fits within `max_length`, otherwise it is truncated at the last whole
    word that fits and an ellipsis is appended.
    """
    words = help.split()
    total_length = 0
    result = []
    done = False

    for word in words:
        if word[-1:] == '.':
            done = True
        new_length = total_length + len(word)
        if new_length > max_length:
            break
        total_length = new_length + 1
        result.append(word)
        if done:
            break

    if len(result) == len(words) or (result and done):
        return ' '.join(result)
    return ' '.join(result) + '...'

